changed /Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/tests/codegen/control_flow/branches_and_loops.rs: // --- FizzBuzz --- -> /// Verifies a comma-separated initializer runs every expression, in order.
///
/// `for ($i = 0, $n = count($a); …)` is textbook PHP and the parser accepted only ONE expression
/// per clause, so the whole loop was refused at parse time.
#[test]
fn test_for_comma_separated_initializer() {
    let out = compile_and_run(
        "<?php $a = [5, 6, 7, 8]; for ($i = 0, $n = count($a); $i < $n; $i++) { echo $a[$i]; }",
    );
    assert_eq!(out, "5678");
}

